// Dummy flood forecasts in the portal's model-forecast format, for testing
// before the portal is connected. Each run raises, escalates or clears alarms.
const now = new Date();
const at = (hours) => new Date(now.getTime() + hours * 3600000).toISOString();
const meta = { simulation_source: 'n8n_dummy_flood_forecast', model_status: 'dummy' };
return [
  { model_case: 'riverine', target_id: 'balloki', target_name: 'Balloki', issued_at: at(0), valid_at: at(12), horizon_hours: 12,
    value: 2950, value_unit: 'cumecs', probability: 0.72, risk_class: 'High', model_name: 'xgboost_riverine_baseline_v1', point_metadata: meta },
  { model_case: 'flash', target_id: 'hill_torrents', target_name: 'Hill torrents', issued_at: at(0), valid_at: at(3), horizon_hours: 3,
    value: 91, value_unit: 'probability_percent', probability: 0.91, risk_class: 'Extreme', model_name: 'lightgbm_flash_flood_baseline_v1', point_metadata: meta },
  { model_case: 'urban', target_id: 'lahore_grid', target_name: 'Lahore urban grid', issued_at: at(0), valid_at: at(6), horizon_hours: 6,
    value: 48, value_unit: 'susceptibility_percent', probability: 0.48, risk_class: 'Moderate', model_name: 'urban_flood_susceptibility_v1', point_metadata: meta },
  { model_case: 'riverine', target_id: 'trimmu', target_name: 'Trimmu', issued_at: at(0), valid_at: at(24), horizon_hours: 24,
    value: 610, value_unit: 'cumecs', probability: 0.12, risk_class: 'Normal', model_name: 'xgboost_riverine_baseline_v1', point_metadata: meta },
  { model_case: 'seasonal', target_id: 'national_basin', target_name: 'Indus national basin', issued_at: at(0), valid_at: at(720), horizon_hours: 720,
    value: 81, value_unit: 'risk_percent', probability: 0.81, risk_class: 'Extremely high', model_name: 'seasonal_outlook_v1', point_metadata: meta },
].map((json) => ({ json }));

// FloodGuard flood alarm settings: edit here. Every run of this workflow
// (portal webhook, dummy test, escalation check) starts from these values.
const settings = {
  // Public base URL of this n8n instance, used in the "acknowledge" link in every alert.
  n8nBaseUrl: 'http://localhost:5678',
  // Shared secret the portal must send in an "x-floodguard-key" header. Empty = no check (local testing only).
  webhookSecret: '',
  // FloodGuard API endpoint that receives every alarm event (raised, escalated, acknowledged, ...).
  // Empty = off. The default is the mock in the "setup & test helpers" workflow.
  backendCallbackUrl: 'http://localhost:5678/webhook/mock-backend',
  backendCallbackKey: '',   // sent as "x-floodguard-key" when set

  // Alarm levels, from the portal's risk_class. A probability at or above
  // `probabilityBump` raises a Warning-or-worse forecast by one level.
  levels: {
    0: { name: 'Normal',  emoji: '🟢', color: '#2e7d32' },
    1: { name: 'Watch',   emoji: '🟡', color: '#f9a825' },
    2: { name: 'Warning', emoji: '🟠', color: '#ef6c00' },
    3: { name: 'Danger',  emoji: '🔴', color: '#c62828' },
    4: { name: 'Extreme', emoji: '🚨', color: '#6a1b9a' },
  },
  riskClassLevels: {
    normal: 0, low: 0, minimal: 0,
    watch: 1, moderate: 1, medium: 1,
    high: 2,
    'very high': 3, 'extremely high': 3, severe: 3,
    extreme: 4, 'exceptionally high': 4, critical: 4,
  },
  probabilityBump: 0.85,

  // The tier of recipients each level starts at. `channels` is only the fallback:
  // the alert_channels data table (Slack / Gmail / WhatsApp toggle per level) wins.
  routing: {
    1: { channels: ['slack'], startTier: 1 },
    2: { channels: ['slack', 'gmail'], startTier: 1 },
    3: { channels: ['slack', 'gmail', 'whatsapp'], startTier: 1 },
    4: { channels: ['slack', 'gmail', 'whatsapp'], startTier: 2 },
  },
  // A repeat forecast at the same (or a lower) level re-alerts only after this many minutes.
  reminderAfterMinutes: { 1: 360, 2: 120, 3: 60, 4: 30 },
  // An open (unacknowledged) alarm moves up one tier after this many minutes without acknowledgement.
  escalateAfterMinutes: { 2: 60, 3: 30, 4: 15 },

  // Escalation tiers. The people (email, WhatsApp) come from the duty_roster
  // data table: whoever is marked on duty at a tier gets that tier's alerts.
  // slackWebhookUrl: a Slack "Incoming Webhook" URL for that tier's channel
  // (the default points at the local mock in the "setup & test helpers" workflow).
  tiers: {
    1: { name: 'District duty officers', slackChannel: '#flood-district-ops',
         slackWebhookUrl: 'http://localhost:5678/webhook/mock-slack' },
    2: { name: 'PDMA provincial control room', slackChannel: '#pdma-control-room',
         slackWebhookUrl: 'http://localhost:5678/webhook/mock-slack' },
    3: { name: 'NDMA national command', slackChannel: '#ndma-command',
         slackWebhookUrl: 'http://localhost:5678/webhook/mock-slack' },
  },

  // Channels. Gmail and WhatsApp are wired but switched off until their
  // credentials are added (next stage); their alerts are logged as "pending_auth".
  channels: {
    slack:    { enabled: true },
    // Gmail sends through smtp.gmail.com with an app password (SMTP credential on "Send Gmail").
    // fromEmail: the Gmail address that credential signs in as.
    gmail:    { enabled: false, fromEmail: '', fromName: 'FloodGuard alarms', note: 'Gmail app password (SMTP credential) pending' },
    whatsapp: { enabled: false, note: 'WhatsApp Business Cloud credential pending', phoneNumberId: '' },
  },
};

const ran = (name) => { try { return $(name).isExecuted; } catch { return false; } };
let trigger = 'forecast-test';
let forecasts = [];
if (ran('Escalation check')) {
  trigger = 'escalation';
} else if (ran('Acknowledge link')) {
  trigger = 'acknowledge';
} else if (ran('Forecast webhook')) {
  trigger = 'forecast-webhook';
  const request = $('Forecast webhook').first().json;
  const body = request.body ?? {};
  forecasts = Array.isArray(body) ? body : Array.isArray(body.forecasts) ? body.forecasts : [body];
  if (settings.webhookSecret && request.headers?.['x-floodguard-key'] !== settings.webhookSecret) {
    // Wrong or missing key: nothing is raised, and the reply says why.
    return [{ json: { trigger, receivedAt: new Date().toISOString(), settings, forecasts: [], rejected: 'missing or wrong x-floodguard-key header', httpStatus: 401 } }];
  }
} else {
  forecasts = $input.all().map((item) => item.json);
}
return [{ json: { trigger, receivedAt: new Date().toISOString(), settings, forecasts } }];

// Who gets what, from two data tables:
//   duty_roster     people on duty, each with a Gmail and a WhatsApp toggle
//                   (turn one off for someone who only has email or only WhatsApp)
//   alert_channels  one row per alarm level with a Slack / Gmail / WhatsApp toggle
const { settings } = $('Alarm settings').first().json;
const toggle = (value, fallback) => value === true || String(value).toLowerCase() === 'true' ? true
  : value === false || String(value).toLowerCase() === 'false' ? false : fallback;
const roster = $('Load duty roster').all().map((item) => item.json)
  .filter((person) => person.name && toggle(person.on_duty, false))
  .map((person) => {
    const email = String(person.email ?? '').trim(), whatsapp = String(person.whatsapp ?? '').trim();
    // A missing toggle column (older table) counts as on.
    const gmail = Boolean(email) && toggle(person.gmail_on, true);
    const wa = Boolean(whatsapp) && toggle(person.whatsapp_on, true);
    return { name: person.name, role: person.role ?? '', tier: Number(person.tier) || 1,
      email: gmail ? email : '', whatsapp: wa ? whatsapp : '', reachable: gmail || wa };
  });
// Channels per level: the alert_channels table, else settings.routing (level 0 = the all-clear).
const fallback = { 0: ['slack', 'gmail'] };
for (const [level, route] of Object.entries(settings.routing)) fallback[level] = route.channels;
const levelChannels = { ...fallback };
const fromTable = [];
for (const { json: row } of $('Load alert channels').all()) {
  if (row.level === undefined || row.level === null || row.level === '') continue;
  const level = Number(row.level);
  levelChannels[level] = ['slack', 'gmail', 'whatsapp'].filter((channel) => toggle(row[channel], false));
  fromTable.push(level);
}
return [{ json: { roster, onDuty: roster.length, levelChannels, levelChannelsFrom: fromTable.length ? 'alert_channels table' : 'settings' } }];

// One item per forecast: validated, labelled and given an alarm level.
const { settings, forecasts, receivedAt } = $('Alarm settings').first().json;
const caseLabels = {
  flash: 'Flash flood', riverine: 'Riverine flood', urban: 'Urban flooding',
  upstream: 'Upstream inflow', seasonal: 'Seasonal flood outlook',
};
const out = [];
forecasts.forEach((raw, index) => {
  const f = raw ?? {};
  const problems = [];
  const targetId = String(f.target_id ?? f.station_id ?? '').trim();
  const targetName = String(f.target_name ?? f.station_name ?? targetId).trim();
  const modelCase = String(f.model_case ?? f.flood_type ?? 'riverine').trim().toLowerCase();
  if (!targetId) problems.push('target_id is missing');
  let probability = f.probability == null ? null : Number(f.probability);
  if (probability != null && probability > 1) probability = probability / 100;   // accept percentages too
  if (probability != null && (!Number.isFinite(probability) || probability < 0 || probability > 1)) problems.push('probability must be 0-1');
  const riskClass = String(f.risk_class ?? '').trim();
  let level = settings.riskClassLevels[riskClass.toLowerCase()];
  if (level == null) {
    if (probability != null) level = probability >= 0.8 ? 3 : probability >= 0.6 ? 2 : probability >= 0.35 ? 1 : 0;
    else problems.push(`unknown risk_class "${riskClass}" and no probability`);
  }
  if (level != null && level >= 2 && level < 4 && probability != null && probability >= settings.probabilityBump) level += 1;
  const value = f.value == null ? null : Number(f.value);
  out.push({ json: {
    index,
    valid: problems.length === 0,
    problems,
    alarm_key: `${modelCase}:${targetId}`,
    model_case: modelCase,
    case_label: caseLabels[modelCase] ?? modelCase,
    target_id: targetId,
    target_name: targetName,
    risk_class: riskClass || (level != null ? settings.levels[level].name : ''),
    level: level ?? 0,
    level_name: settings.levels[level ?? 0].name,
    probability,
    value: Number.isFinite(value) ? value : null,
    value_unit: String(f.value_unit ?? ''),
    issued_at: String(f.issued_at ?? receivedAt),
    valid_at: String(f.valid_at ?? f.issued_at ?? receivedAt),
    horizon_hours: Number(f.horizon_hours ?? 0),
    model_name: String(f.model_name ?? ''),
    source: String(f.point_metadata?.simulation_source ?? f.source ?? 'portal'),
    // Identifies this exact forecast: the portal's id when it sends one, else its issue time and content.
    ref: String(f.id ?? f.forecast_id ?? f.alert_id ?? `${f.issued_at ?? ''}|${riskClass}|${f.value ?? ''}|${f.probability ?? ''}`),
  } });
});
return out;

// What to do with each forecast, given the alarms already open:
//   raise           new alarm (Watch or worse)          -> alert
//   escalate_level  forecast worse than the open alarm  -> alert at once
//   reminder        same/lower level, reminder interval passed -> alert again
//   update          same/lower level, within the interval -> record only
//   resolve         back to Normal while an alarm is open -> all-clear alert
//   record          Normal and nothing open              -> nothing to do
//   invalid         forecast failed validation           -> reported back only
//   duplicate       this exact forecast was already processed -> ignored
// Alarms that need people (Warning and worse) start at the first tier that has
// someone on duty in the duty_roster table; skipped tiers are noted.
const { settings } = $('Alarm settings').first().json;
const roster = $('Duty roster').first().json.roster ?? [];
const now = new Date(), nowIso = now.toISOString();
const minutesSince = (iso) => iso ? (now - new Date(iso)) / 60000 : Infinity;
const open = new Map($('Load open alarms').all().map((i) => i.json).filter((r) => r.alarm_id).map((r) => [r.alarm_key, r]));
const tierName = (tier) => settings.tiers[tier]?.name ?? `Tier ${tier}`;
const maxTier = Math.max(...Object.keys(settings.tiers).map(Number));
const staffed = (tier) => roster.some((person) => person.tier === tier && person.reachable);
const seen = new Set();

return $('Normalize & classify').all().filter(({ json: f }) => f.index !== undefined).map(({ json: f }) => {
  if (!f.valid) return { json: { ...f, action: 'invalid', notify: false } };
  const existing = open.get(f.alarm_key);
  const refKey = `${f.alarm_key}#${f.ref}`;
  if (seen.has(refKey) || (existing && existing.last_forecast_ref === f.ref)) {
    return { json: { ...f, action: 'duplicate', notify: false, alarm_id: existing?.alarm_id ?? null } };
  }
  seen.add(refKey);
  const routing = settings.routing[Math.max(1, f.level)];
  let action, tier, alarm;
  if (f.level === 0) {
    action = existing ? 'resolve' : 'record';
  } else if (!existing) {
    action = 'raise';
  } else if (f.level > Number(existing.level)) {
    action = 'escalate_level';
  } else {
    action = minutesSince(existing.last_notified_at) >= (settings.reminderAfterMinutes[existing.level] ?? 120) ? 'reminder' : 'update';
  }
  if (action === 'record') return { json: { ...f, action, notify: false } };

  const base = existing ?? {
    alarm_id: `FG-${f.model_case}-${f.target_id}-${now.getTime().toString(36)}`.toUpperCase(),
    status: 'open', tier: routing.startTier, escalations: 0, notify_count: 0,
    first_raised_at: nowIso, last_notified_at: '', acknowledged_by: '', acknowledged_at: '', resolved_at: '',
  };
  // A worse forecast reopens an acknowledged alarm and never lowers its tier.
  const level = action === 'resolve' ? Number(existing.level) : action === 'update' || action === 'reminder' ? Math.max(f.level, Number(existing?.level ?? 0)) : f.level;
  tier = Math.max(Number(base.tier) || 1, settings.routing[Math.max(1, level)].startTier);
  // Nobody on duty at that tier: move on to the next tier that has someone.
  const skippedTiers = [];
  if (level >= 2 && action !== 'resolve') {
    while (tier < maxTier && !staffed(tier)) { skippedTiers.push(tier); tier += 1; }
  }
  const notify = ['raise', 'escalate_level', 'reminder', 'resolve'].includes(action);
  alarm = {
    ...base,
    alarm_key: f.alarm_key, model_case: f.model_case, case_label: f.case_label,
    target_id: f.target_id, target_name: f.target_name,
    level, level_name: settings.levels[level].name,
    forecast_level: f.level, risk_class: f.risk_class,
    probability: f.probability, value: f.value, value_unit: f.value_unit,
    issued_at: f.issued_at, valid_at: f.valid_at, horizon_hours: f.horizon_hours,
    model_name: f.model_name, source: f.source,
    status: action === 'resolve' ? 'resolved' : action === 'escalate_level' ? 'open' : base.status,
    resolved_at: action === 'resolve' ? nowIso : base.resolved_at,
    tier, tier_name: tierName(tier),
    notify_count: Number(base.notify_count || 0) + (notify ? 1 : 0),
    last_notified_at: notify ? nowIso : base.last_notified_at,
    last_forecast_at: nowIso,
    last_forecast_ref: f.ref,
    last_action: action,
  };
  // Later forecasts in the same batch see this alarm as the open one.
  open.set(f.alarm_key, alarm);
  return { json: { ...alarm, action, notify, previous_level: existing ? Number(existing.level) : null, skipped_tiers: skippedTiers } };
});

// Open alarms nobody has acknowledged in time move up one tier of recipients,
// skipping tiers with nobody on duty. An alarm whose tier has nobody on duty
// (someone went off duty) moves on at once.
const { settings } = $('Alarm settings').first().json;
const roster = $('Duty roster').first().json.roster ?? [];
const now = new Date(), nowIso = now.toISOString();
const maxTier = Math.max(...Object.keys(settings.tiers).map(Number));
const staffed = (tier) => roster.some((person) => person.tier === tier && person.reachable);
const due = [];
for (const { json: row } of $input.all()) {
  if (!row.alarm_id || row.status !== 'open') continue;
  const level = Number(row.level), tier = Number(row.tier) || 1;
  const after = settings.escalateAfterMinutes[level];
  if (!after || tier >= maxTier) continue;
  const minutes = (now - new Date(row.last_notified_at || row.first_raised_at)) / 60000;
  const unstaffed = !staffed(tier);
  if (minutes < after && !unstaffed) continue;
  let next = tier + 1;
  const skippedTiers = unstaffed ? [tier] : [];
  while (next < maxTier && !staffed(next)) { skippedTiers.push(next); next += 1; }
  due.push({ json: {
    ...row,
    tier: next, tier_name: settings.tiers[next]?.name ?? `Tier ${next}`,
    escalations: Number(row.escalations || 0) + 1,
    notify_count: Number(row.notify_count || 0) + 1,
    last_notified_at: nowIso, last_action: 'escalate_tier',
    action: 'escalate_tier', notify: true, unacknowledged_minutes: Math.round(minutes),
    escalation_reason: unstaffed ? `nobody on duty at tier ${tier}` : `not acknowledged for ${Math.round(minutes)} min`,
    skipped_tiers: skippedTiers,
  } });
}
return due;   // nothing due: the run stops here

