={{ (() => {
  const row = $json;
  const ok = Boolean(row.alarm_id);
  const title = ok ? 'Alarm acknowledged' : 'Alarm not found';
  const body = ok
    ? `<p><b>${row.alarm_id}</b> (${row.level_name} – ${row.target_name}) is acknowledged by <b>${row.acknowledged_by}</b>.</p><p>It will not be escalated further. A worse forecast will still raise it again.</p>`
    : `<p>No alarm matches <b>${$('Acknowledge link').first().json.query?.alarm_id ?? '(no id)'}</b>.</p>`;
