<body style="font-family:Arial,sans-serif;max-width:520px;margin:48px auto;padding:0 16px;color:#123">
<h2 style="color:${ok ? '#2e7d32' : '#c62828'}">${title}</h2>${body}<p style="color:#777;font-size:12px">FloodGuard flood alarm</p></body></html>`;
