parameters.jsCode:
// The alarm as stored in the flood_alarms data table (only its columns).
const columns = ['alarm_id', 'alarm_key', 'status', 'level', 'level_name', 'risk_class', 'model_case', 'target_id',
  'target_name', 'value', 'value_unit', 'probability', 'issued_at', 'valid_at', 'model_name', 'source', 'tier',
  'tier_name', 'escalations', 'notify_count', 'first_raised_at', 'last_forecast_at', 'last_notified_at',
  'last_action', 'last_forecast_ref', 'acknowledged_by', 'acknowledged_at', 'resolved_at'];
const numbers = new Set(['level', 'value', 'probability', 'tier', 'escalations', 'notify_count']);
// Duplicates, invalid and normal-only forecasts leave the stored alarm as it is.
return $input.all()
  .filter((item) => item.json.alarm_id && !['duplicate', 'invalid', 'record'].includes(item.json.action))
  .map((item) => {
    const row = {};
    for (const column of columns) {
      const value = item.json[column];
      row[column] = numbers.has(column) ? (value == null || value === '' ? 0 : Number(value)) : (value == null ? '' : String(value));
    }
    return { json: row, pairedItem: item.pairedItem };
  });

// The reply to the portal: what happened to each forecast it sent, with an
// HTTP status: 202 accepted, 400 nothing usable, 401 wrong key.
const run = $('Alarm settings').first().json;
if (run.trigger !== 'forecast-webhook') return [];
const decisions = $('Decide action').all().map((i) => i.json).filter((d) => d.target_id !== undefined);
const usable = decisions.filter((d) => d.action !== 'invalid');
const http_status = run.httpStatus ?? (usable.length ? 202 : 400);
return [{ json: {
  http_status,
  ...(run.rejected ? { rejected: run.rejected } : {}),
  ...(!run.rejected && !usable.length ? { error: decisions.length ? 'no valid forecast in the request' : 'no forecasts in the request' } : {}),
  duplicates: decisions.filter((d) => d.action === 'duplicate').length,
  received: decisions.length,
  alerts_sent: decisions.filter((d) => d.notify).length,
  alarms: decisions.map((d) => ({
    target: d.target_name, model_case: d.model_case, level: d.level, level_name: d.level_name,
    action: d.action, alarm_id: d.alarm_id ?? null, tier: d.tier ?? null, problems: d.problems?.length ? d.problems : undefined,
  })),
} }];

// The audit trail: one alarm_events row per change of an alarm's state.
const names = {
  raise: 'raised', escalate_level: 'level_escalated', reminder: 'reminder_sent', update: 'forecast_updated',
  resolve: 'resolved', escalate_tier: 'tier_escalated',
};
const at = new Date().toISOString();
const events = [];
for (const { json: a } of $input.all()) {
  if (!a.alarm_id) continue;
  const acknowledged = !a.action && a.last_action === 'acknowledge';
  const event = acknowledged ? 'acknowledged' : names[a.action];
  if (!event) continue;
  const base = { alarm_id: a.alarm_id, level: Number(a.level) || 0, tier: Number(a.tier) || 1 };
  for (const tier of a.skipped_tiers ?? []) {
    events.push({ json: { ...base, event: 'no_recipient', actor: 'n8n', detail: `nobody on duty at tier ${tier} with email or WhatsApp switched on; moved on`, at } });
  }
  events.push({ json: { ...base, event,
    actor: acknowledged ? String(a.acknowledged_by || 'link in alert') : 'n8n',
    detail: acknowledged ? 'acknowledged from the alert link'
      : a.action === 'escalate_tier' ? `${a.escalation_reason}; now with ${a.tier_name}`
      : `${a.level_name}${a.previous_level != null && a.previous_level !== a.level ? ` (was level ${a.previous_level})` : ''} · ${a.risk_class || ''} · ${a.target_name}`,
    at } });
}
return events;

// What the FloodGuard backend is told: every alarm event of this run, in one call.
const run = $('Alarm settings').first().json;
if (!run.settings.backendCallbackUrl) return [];
const events = $input.all().map((item) => item.json).filter((event) => event.alarm_id);
if (!events.length) return [];
return [{ json: {
  url: run.settings.backendCallbackUrl,
  key: run.settings.backendCallbackKey ?? '',
  body: { source: 'n8n-flood-alarm', trigger: run.trigger, sent_at: new Date().toISOString(),
    events: events.map(({ alarm_id, event, level, tier, actor, detail, at }) => ({ alarm_id, event, level, tier, actor, detail, at })) },
} }];

// The backend call goes into alarm_notifications like any other delivery.
const request = $('Callback payload').first().json;
const result = $input.first().json;
const error = result.error;
return [{ json: {
  alarm_id: request.body.events.map((event) => event.alarm_id).filter((id, i, all) => all.indexOf(id) === i).join(', ').slice(0, 250),
  action: 'callback', level: Math.max(...request.body.events.map((event) => event.level)), tier: 0,
  channel: 'backend', recipient: request.url, status: error ? 'failed' : 'sent',
  detail: error ? String(error.message ?? JSON.stringify(error)).slice(0, 500) : `${request.body.events.length} events`,
  message: JSON.stringify(request.body).slice(0, 1500), sent_at: new Date().toISOString(),
} }];

// One message per channel and recipient for every alarm that needs an alert.
// Email and WhatsApp go to whoever is on duty at the tier (duty_roster table);
// a channel with nobody on duty is logged as "no_recipient".
const { settings } = $('Alarm settings').first().json;
const { roster = [], levelChannels = {} } = $('Duty roster').first().json;
const ackBase = `${settings.n8nBaseUrl}/webhook/flood-alarm/ack`;
const out = [];
for (const { json: a } of $input.all()) {
  if (!a.notify) continue;
  const level = settings.levels[a.level] ?? settings.levels[0];
  const pct = a.probability == null || a.probability === '' ? 'n/a' : `${Math.round(Number(a.probability) * 100)}%`;
  const value = a.value == null || a.value === '' ? '' : `${a.value} ${String(a.value_unit).replace(/_/g, ' ')}`;
  const headline = {
    raise: `${level.emoji} ${level.name.toUpperCase()}: ${a.case_label ?? a.model_case} forecast at ${a.target_name}`,
    escalate_level: `${level.emoji} ESCALATED to ${level.name.toUpperCase()}: ${a.case_label ?? a.model_case} at ${a.target_name}`,
    reminder: `${level.emoji} REMINDER (${level.name}): ${a.case_label ?? a.model_case} at ${a.target_name} is still forecast`,
    resolve: `${settings.levels[0].emoji} ALL CLEAR: ${a.case_label ?? a.model_case} at ${a.target_name} is back to normal`,
    escalate_tier: `${level.emoji} UNACKNOWLEDGED ${level.name.toUpperCase()} alarm escalated to ${a.tier_name}: ${a.target_name}`,
  }[a.action] ?? `${level.emoji} ${a.target_name}`;
  const ackUrl = `${ackBase}?alarm_id=${encodeURIComponent(a.alarm_id)}`;
  const lines = [
    headline,
    `Risk: ${a.risk_class || level.name} · alarm level ${a.level} (${level.name}) · probability ${pct}`,
    value && `Forecast value: ${value}`,
    `Valid at: ${a.valid_at}${a.horizon_hours ? ` (+${a.horizon_hours} h)` : ''} · model ${a.model_name || 'n/a'}`,
    a.action === 'escalate_tier' ? `Escalated because: ${a.escalation_reason}; now with ${a.tier_name}.` : `Recipients: ${a.tier_name} (tier ${a.tier})`,
    a.skipped_tiers?.length ? `Skipped tier ${a.skipped_tiers.join(', ')}: nobody on duty with email or WhatsApp switched on.` : '',
    `Alarm ID: ${a.alarm_id}`,
    a.action !== 'resolve' && `Acknowledge: ${ackUrl}`,
  ].filter(Boolean);
  const text = lines.join('\n');
  const html = `<div style="font-family:Arial,sans-serif;max-width:560px">
<div style="background:${level.color};color:#fff;padding:12px 16px;border-radius:6px 6px 0 0;font-weight:bold">${headline}</div>
<div style="border:1px solid #ddd;border-top:0;padding:12px 16px;border-radius:0 0 6px 6px;line-height:1.5">
${lines.slice(1).filter((l) => !l.startsWith('Acknowledge')).map((l) => `<div>${l}</div>`).join('\n')}
${a.action !== 'resolve' ? `<p><a href="${ackUrl}" style="background:${level.color};color:#fff;padding:8px 14px;border-radius:4px;text-decoration:none">Acknowledge alarm</a></p>` : ''}
<p style="color:#777;font-size:12px">FloodGuard flood alarm · ${new Date().toISOString()}</p></div></div>`;

  // Tier escalations go to the new tier only; everything else to every tier up to the alarm's.
  const tiers = a.action === 'escalate_tier' ? [a.tier] : Array.from({ length: a.tier }, (_, i) => i + 1);
  // Channels switched on for this level in alert_channels (an all-clear uses the level 0 row).
  const channels = levelChannels[a.action === 'resolve' ? 0 : a.level] ?? [];
  for (const tierNumber of tiers) {
    const tier = settings.tiers[tierNumber];
    if (!tier) continue;
    for (const channel of channels) {
      const config = settings.channels[channel] ?? {};
      const onDuty = roster.filter((person) => person.tier === tierNumber);
      const recipients = channel === 'slack' ? [tier.slackChannel]
        : (channel === 'gmail' ? onDuty.map((person) => person.email) : onDuty.map((person) => person.whatsapp)).filter(Boolean);
      // Nobody on duty with this channel switched on: record it rather than send nothing silently.
      for (const recipient of recipients.length ? recipients : ['(nobody on duty)']) {
        let status = 'ready';
        if (!recipients.length) status = 'no_recipient';
        else if (!config.enabled) status = 'pending_auth';
        else if (channel === 'slack' && !tier.slackWebhookUrl) status = 'not_configured';
        else if (channel === 'whatsapp' && !config.phoneNumberId) status = 'not_configured';
        else if (channel === 'gmail' && !config.fromEmail) status = 'not_configured';
        out.push({ json: {
          alarm_id: a.alarm_id, action: a.action, level: a.level, level_name: a.level_name, tier: tierNumber,
          channel, recipient, ready: status === 'ready', delivery_status: status,
          delivery_detail: status === 'pending_auth' ? (config.note ?? 'credential pending') : status === 'not_configured' ? 'no destination configured'
            : status === 'no_recipient' ? `nobody on duty at tier ${tierNumber} with ${channel === 'gmail' ? 'Gmail' : 'WhatsApp'} switched on` : '',
          slack_webhook_url: channel === 'slack' ? tier.slackWebhookUrl : '',
          whatsapp_phone_number_id: config.phoneNumberId ?? '',
          email_from: channel === 'gmail' && config.fromEmail ? `${config.fromName ?? 'FloodGuard alarms'} <${config.fromEmail}>` : '',
          subject: headline.replace(/^[^A-Za-z]+/, ''), text, html,
        } });
      }
    }
  }
}
return out;

// One row per delivery attempt for the alarm_notifications data table.
return $input.all().map((item, index) => {
  const message = $('Build messages').itemMatching(index).json;
  const result = item.json;
  let status = result.delivery_status;
  let detail = result.delivery_detail ?? '';
  if (message.ready && result.text === message.text && result.channel === message.channel) {
    // The send node handed the message straight through: it is switched off (disabled) in the workflow.
    status = 'failed';
    detail = `${message.channel} send node is disabled in the workflow`;
  } else if (message.ready) {
    const error = result.error;
    status = error ? 'failed' : 'sent';
    detail = error ? String(error.message ?? error.description ?? JSON.stringify(error)).slice(0, 500)
      : String(result.id ?? result.messageId ?? result.messages?.[0]?.id ?? result.data ?? 'delivered').slice(0, 200);
  }
  return { json: {
    alarm_id: message.alarm_id, action: message.action, level: Number(message.level) || 0, tier: Number(message.tier) || 1,
    channel: message.channel, recipient: message.recipient, status, detail: detail || '',
    message: message.text.slice(0, 1500), sent_at: new Date().toISOString(),
  } };
});

